export interface TemplateEditorial {
  topic: string;
  intro: string[];
  faqs: { question: string; answer: string }[];
  updated: string;
}

function reviewed(topic: string, intro: string, faqs: [string, string][]): TemplateEditorial {
  return { topic, intro: intro.split("\n\n"), faqs: faqs.map(([question, answer]) => ({ question, answer })), updated: "2026-10-27" };
}

